-- compare_f.tsv: for each literal, how many rows of t `f <op> <literal>` keeps, the
-- sum of their id, and how many rows DuckDB cannot decide (the comparison raises a
-- conversion error: TRY gives NULL for a row whose f is not NULL), for each of the six
-- comparison operators. The literal is the SQL text the test runs too (a folded bound is
-- written as the arithmetic), so the file holds DuckDB's reading of it. NULL rows are in
-- neither the kept rows nor their complement. Column f is DECIMAL(38, 10).
COPY (
SELECT * FROM (
  SELECT 0 AS n, 'f' AS col, '0.0000000003' AS lit,
    (SELECT count(*) FROM t WHERE TRY(f < 0.0000000003)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f < 0.0000000003)) AS lt_s, (SELECT count(*) FROM t WHERE TRY(f < 0.0000000003) IS NULL AND f IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM t WHERE TRY(f <= 0.0000000003)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f <= 0.0000000003)) AS le_s, (SELECT count(*) FROM t WHERE TRY(f <= 0.0000000003) IS NULL AND f IS NOT NULL) AS le_e,
    (SELECT count(*) FROM t WHERE TRY(f > 0.0000000003)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f > 0.0000000003)) AS gt_s, (SELECT count(*) FROM t WHERE TRY(f > 0.0000000003) IS NULL AND f IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM t WHERE TRY(f >= 0.0000000003)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f >= 0.0000000003)) AS ge_s, (SELECT count(*) FROM t WHERE TRY(f >= 0.0000000003) IS NULL AND f IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM t WHERE TRY(f = 0.0000000003)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f = 0.0000000003)) AS eq_s, (SELECT count(*) FROM t WHERE TRY(f = 0.0000000003) IS NULL AND f IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM t WHERE TRY(f <> 0.0000000003)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f <> 0.0000000003)) AS ne_s, (SELECT count(*) FROM t WHERE TRY(f <> 0.0000000003) IS NULL AND f IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 1 AS n, 'f' AS col, '0.00000000005' AS lit,
    (SELECT count(*) FROM t WHERE TRY(f < 0.00000000005)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f < 0.00000000005)) AS lt_s, (SELECT count(*) FROM t WHERE TRY(f < 0.00000000005) IS NULL AND f IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM t WHERE TRY(f <= 0.00000000005)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f <= 0.00000000005)) AS le_s, (SELECT count(*) FROM t WHERE TRY(f <= 0.00000000005) IS NULL AND f IS NOT NULL) AS le_e,
    (SELECT count(*) FROM t WHERE TRY(f > 0.00000000005)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f > 0.00000000005)) AS gt_s, (SELECT count(*) FROM t WHERE TRY(f > 0.00000000005) IS NULL AND f IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM t WHERE TRY(f >= 0.00000000005)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(f >= 0.00000000005)) AS ge_s, (SELECT count(*) FROM t WHERE TRY(f >= 0.00000000005) IS NULL AND f IS NOT NULL) AS ge_e,
